class MutableMoney {
public:
    MutableMoney(std::string currency, double amount)
        : currency_(std::move(currency)), amount_(amount) {}

    void setAmount(double amount) { amount_ = amount; } // danger
    double getAmount() const { return amount_; }
    std::string getCurrency() const { return currency_; }

private:
    std::string currency_;
    double amount_;
};

int main() {
    std::vector<std::shared_ptr<MutableMoney>> cart;
    auto price = std::make_shared<MutableMoney>("USD", 100.0);
    cart.push_back(price);
    std::cout << "Before mutation: " << cart[0]->getAmount() << std::endl;
    price->setAmount(0.0);  // danger: silently corrupts the cart!
    std::cout << "After mutation: " << cart[0]->getAmount() << std::endl;
    return 0;
}

