    int year() const { return year_; }
    int month() const { return month_; }
    int day() const { return day_; }

private:
    const int year_;
    const int month_;
    const int day_;
};

int main() {
    Date today(2024, 1, 15);

    Date tomorrow = today.plusDays(1);   // new object

    std::cout << today.year() << "-" << today.month() << "-" << today.day() << std::endl;        // 2024-1-15 -- unchanged
    std::cout << tomorrow.year() << "-" << tomorrow.month() << "-" << tomorrow.day() << std::endl; // 2024-1-16
    return 0;
}

