#include <iostream>
#include <string>

struct Money {  // aggregate value type -- immutable by convention (const members)
    const std::string currency;
    const double amount;
};

std::ostream& operator<<(std::ostream& os, const Money& m) {
    return os << "Money[currency=" << m.currency << ", amount=" << m.amount << "]";
}

int main() {
    Money price{"USD", 100.0};

    Money discounted{price.currency, price.amount - 10};

    std::cout << price << std::endl;       // Money[currency=USD, amount=100] -- untouched
    std::cout << discounted << std::endl;  // Money[currency=USD, amount=90]
    return 0;
}
